head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07403";
scwin.SCREN_PROCS_TP_CD_01 = "01";  // 조회 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.TR_JOB_INSERT = 2;  // 입력 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.NO_EXCEL_DATA = "해당데이터가 없습니다. 조회후 다운받으십시요.";  // 엑셀 다운로드 데이터 없음 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.grd_Grid = null;
scwin.btn_Excel = null;
scwin.btn_New = null;
scwin.panel_page = null;
scwin.btn_Modify = null;
scwin.btn_Delete = null;
scwin.btn_Select = null;
scwin.isSetPopup = false;
scwin.isMailPopup = true;
scwin.dts_List = null;
scwin.dts_Cod = null;
scwin.pMenuID = undefined;
scwin.fn_trs = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    try {
        await scwin.searchCode();
        await scwin.grdSearchCode();
        await scwin.listSync();
        const parentWin = $c.win.getParent();
        const parScrenId = parentWin.vScrenID;
        if (parScrenId === "ULDSTF07041.gfm" || parScrenId === "ULDSTF07404.gfm") {
            scwin.isSetPopup = true;
            scwin.setPar = parentWin.fn_SetPar;
            scwin.showObj(scwin.btn_New, false);
            scwin.showObj(scwin.btn_Delete, false);
            scwin.showObj(scwin.btn_Modify, false);
            scwin.showObj(scwin.btn_Excel, false);
        }
        if (parScrenId !== "ULDSTF07404.gfm") {
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_Grid.getColumnInfo("CHK_YN", "Show") */
            scwin.showObj(scwin.btn_Select, false);
            scwin.isMailPopup = false;
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pMenuID =$c.win.getProgramId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07403' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd_Grid = $c.util.getComponent('grd_Grid');
        scwin.btn_Excel = $c.util.getComponent('btn_Excel');
        scwin.btn_New = $c.util.getComponent('btn_New');
        scwin.panel_page = $c.util.getComponent('panel_page');
        scwin.btn_Modify = $c.util.getComponent('btn_Modify');
        scwin.btn_Delete = $c.util.getComponent('btn_Delete');
        scwin.btn_Select = $c.util.getComponent('btn_Select');
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');
        scwin.fn_trs = scwin.sbm_trs_Save;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07403.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search1_onclick
 * @description btn_Search1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search1_onclick = async function () {
    try {
        await scwin.listSync();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Search1_onclick' }); }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function () {
    try {
        if (scwin.dts_List.CountRow > 0) {
            /* TODO Stage2: 접속 로그 저장 보류(공급사 doLogSave — 운영 필요 여부 회신 ㉤ 뒤 결정) $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07); */
            scwin.grd_Grid.GridToOffice("평가기관담당자", "", 8, 0);
        } else {
            await $c.win.alert(scwin.NO_EXCEL_DATA);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name dts_List_onloadcompleted
 * @description dts_List onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloadcompleted = function (rowcount) {
    try {
        scwin.showTotalCount(rowcount, scwin.panel_page);
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07403.dts_List_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_List_onloaderror
 * @description dts_List onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07403.dts_List_onloaderror" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description btn_New 의 onclick 에서 dts_List 을(를) 행을 추가한다
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function () {
    try {
        scwin.dts_List.insertRow();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07403.btn_New_onclick' }); }
};

/**
 * @method
 * @name txb_CHRG_NM_onkeydown
 * @description txb_CHRG_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CHRG_NM_onkeydown = async function () {
    try {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.listSync();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.txb_CHRG_NM_onkeydown' }); }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description btn_Delete 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function () {
    try {
        scwin.dts_List.removeRow(scwin.dts_List.getRowPosition());

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Delete_onclick' }); }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description btn_Modify 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function () {
    try {
        await scwin.save();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Modify_onclick' }); }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await scwin.alertJobResult('F');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07403.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description trs_Save onsuccess 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await scwin.alertJobResult('S');
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07403.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name grd_Grid_ondblclick
 * @description grd_Grid 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_ondblclick = function (row, colid) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        if (scwin.isSetPopup && !scwin.isMailPopup) {
            const arrPar = [];
            if (scwin.setPar != null) {
                arrPar[0] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'CHRG_NM');
                arrPar[1] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'COM_TEL_NO');
                arrPar[2] = scwin.dts_List.getCellData(scwin.dts_List.getRowPosition(), 'CHRG_EMAIL');
                scwin.setPar(arrPar);
            }
            $c.win.closePopup();
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07403.grd_Grid_ondblclick' }); }
};

/**
 * @method
 * @name btn_Select_onclick
 * @description btn_Select 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Select_onclick = function () {
    try {
        scwin.chkSelect();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07403.btn_Select_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.tx_script_dts_Cod
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
 */
// TODO Stage2: 중복 정의 — as-is 에서 뒤 정의에 덮여 호출되지 않던 본문(JS 는 마지막 정의가 이긴다). 필요 없으면 삭제 — 원이름 tx_script_dts_Cod

/**
 * @method
 * @name tx_script_dts_Cod_1
 * @description script dts Cod 1 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_Cod_1 = async function () {
    $c.util.getComponent("dma_scriptDts_CodReq").set("SCREN_ID", "ULDSTF07403.gfm");
    $c.util.getComponent("dma_scriptDts_CodReq").set("inputMessageId", "CODE_M_IN");
    $c.util.getComponent("dma_scriptDts_CodReq").set("outputMessageId", "CODE_M_OUT");
    $c.util.getComponent("dma_scriptDts_CodReq").set("CD_ID_M", "'SPECY_VALU_INST_CD'");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_Cod",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDts_CodReq",
        target: "dts_Cod=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Cod_onloaderror'] === 'function') ? scwin['dts_Cod_onloaderror'] : (typeof scwin['dts_Cod_onfail'] === 'function') ? scwin['dts_Cod_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Cod_onloadcompleted'] === 'function') ? scwin['dts_Cod_onloadcompleted'] : ((typeof scwin['dts_Cod_onsuccess'] === 'function') ? scwin['dts_Cod_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Cod'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07403.tx_script_dts_Cod" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

