///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function () {
    const arrCid = [{ cid: "SPECY_VALU_INST_CD", cnm: "cmb_SPECY_VALU_INST_CD" }];
    let objCod;
    const url = "/CodeAction.do?SCREN_ID=" + "ULDSTF07403.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD'";

    await scwin.tx_script_dts_Cod();
    let strCbd = "", i, j;
    strCbd = "''^''전체";
    for (i = 0; i < arrCid.length; i++) {
        objCod = $c.util.getComponent(arrCid[i].cnm);
        if (objCod == null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        for (j = 1; j <= scwin.dts_Cod.CountRow; j++) {
            if (scwin.dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + scwin.dts_Cod.getCellData(j, "VALUE") + "^" + scwin.dts_Cod.getCellData(j, "TEXT");
            }
        }
        if(objCod)objCod.CBData=strCbd;
    }
};

/**
 * @method
 * @name grdSearchCode
 * @description grd Search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grdSearchCode = async function () {
    const url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD', 'SPECY_VALU_INST_TP_CD'";

    await scwin.tx_script_dts_Cod();
    strCbdReason = "' ':";
    for (k = 1; k <= scwin.dts_Cod.CountRow; k++) {
        if (scwin.dts_Cod.getCellData(k, "CD_ENG_NM") === "SPECY_VALU_INST_CD") {
            strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + scwin.dts_Cod.getCellData(k, "VALUE") + ":" + scwin.dts_Cod.getCellData(k, "TEXT");
        }
    }
    /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_Grid.getColumnInfo('SPECY_VALU_INST_CD', 'Data') */
    strCbdReason = "' ':";
    for (k = 1; k <= scwin.dts_Cod.CountRow; k++) {
        if (scwin.dts_Cod.getCellData(k, "CD_ENG_NM") === "SPECY_VALU_INST_TP_CD") {
            strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + scwin.dts_Cod.getCellData(k, "VALUE") + ":" + scwin.dts_Cod.getCellData(k, "TEXT");
        }
    }
    /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_Grid.getColumnInfo('SPECY_VALU_INST_TP_CD', 'Data') */
};

/**
