 */
scwin.listSync = async function () {
    let url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + "ULDSTF07403.gfm" + "&SCREN_PROCES_TP_CD=" + scwin.SCREN_PROCS_TP_CD_01 + "&method=selectValuInstPnt&inputMessageId=VALU_INST_PNT_INOUT";
