    await scwin.tx_script_dts_List();
    void 0;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!await scwin.confirmJob(TR_JOB)) {
            return;
        }
        scwin.fn_trs(scwin.TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    for (let i = 1, j = scwin.dts_List.CountRow; i <= j; i++) {
        const status = scwin.dts_List.getRowStatus(i);
        if (status === 1 || status === 3) {
            if (scwin.dts_List.getCellData(i, "SPECY_VALU_INST_CD") === "") {
                await $c.win.alert(i + "번째행" + " 기관명은 필수값입니다.");
                return false;
            }
            if (scwin.dts_List.getCellData(i, "SPECY_VALU_INST_TP_CD") === "") {
                await $c.win.alert(i + "번째행" + " 구분값은 필수값입니다.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name chkSelect
 * @description chk Select 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkSelect = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    let arrPar;
    let selNum = 0;
    let isFirst = true;
    for (let i = 1, j = scwin.dts_List.CountRow; i <= j; i++) {
        if (scwin.dts_List.getCellData(i, "CHK_YN") === "T") {
            arrPar = [];
            arrPar[0] = scwin.dts_List.getCellData(i, 'CHRG_NM');
            arrPar[1] = scwin.dts_List.getCellData(i, 'CHRG_EMAIL');
            selNum++;
            if (scwin.setPar != null) {
                if (selNum !== 1) {
                    isFirst = false;
                }
                scwin.setPar(arrPar, isFirst);
            }
        }
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function (arrPar) {
    txb_ISUR_CD.value = arrPar[0].ISUR_CD;
    txb_COM_NM.value = arrPar[0].COM_NM;
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name showObj
 * @description 컴포넌트 표시/숨김(as-is 공통 showObj — id 문자열 또는 컴포넌트)
 * @param {Object} obj 컴포넌트 id 또는 컴포넌트
 * @param {String} flag true 표시 · false 숨김
 * @returns {void}
 * @hidden N
 */
scwin.showObj = function (obj, flag) {
    const comp = (typeof obj === "string") ? $c.util.getComponent(obj) : obj;
    if (!comp) { return; }
    if (flag) { comp.show(); } else { comp.hide(); }
};

/**
 * @method
 * @name showTotalCount
 * @description 목록 총건수 표시(as-is 공통 FillGridHeaderTotalCnt — 패널 안에 「총건수: N」)
 * @param {*} count 건수
 * @param {*} panel 표시할 그룹 id 또는 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showTotalCount = function (count, panel) {
    const comp = (typeof panel === "string") ? $c.util.getComponent(panel) : panel;
    if (comp && comp.render) {
        comp.render.innerHTML = '<span class="count">총건수: <strong>' + $c.num.formatNumber(count) + "</strong></span>";
    }
};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};

/**
 * @method
 * @name alertJobResult
 * @description 업무 처리 결과 알림 — S "[처리명] 처리 성공하였습니다." · S1 "성공적으로 처리되었습니다." · F "[처리명] 처리 실패하였습니다."
 * @param {*} gubun 결과 구분(S 성공 · S1 성공(처리명 없음) · F 실패)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertJobResult = async function (gubun) {
    const job = scwin.lastJob || "";
    if (gubun === "S") { await $c.win.alert("[" + job + "] 처리 성공하였습니다."); }
    else if (gubun === "S1") { await $c.win.alert("성공적으로 처리되었습니다."); }
    else if (gubun === "F") { await $c.win.alert("[" + job + "] 처리 실패하였습니다."); }
};
